import { z } from 'zod';

/**
 * TypeScript 타입에 대한 기본 스키마 생성
 * 실제로는 각 필드마다 세부 검증 규칙을 추가해야 합니다
 */
export function createBaseSchema<T>() {
  // 타입 정보는 런타임에 존재하지 않으므로
  // 기본 객체 스키마를 반환합니다
  return z.object({}) as unknown as z.ZodType<T>;
}

/**
 * 더 실용적인 접근법 - 타입과 스키마를 함께 정의하기
 *
 * 예시:
 * const userParamsSchema = z.object({
 *   ci: z.string(),
 *   cstmrNo: z.string(),
 *   // ...
 * });
 *
 * type UserParams = z.infer<typeof userParamsSchema>;
 */

/**
 * Validates props against a Zod schema and handles errors gracefully
 *
 * This utility function validates component props against their schema,
 * logs any validation errors to the console, but allows the component
 * to continue functioning with the original props to prevent crashes.
 *
 * @param schema - The Zod schema to validate against
 * @param props - The props to validate
 * @param componentName - The name of the component (for error messages)
 * @returns The validated props or the original props if validation fails
 */
export function validateProps<T>(schema: z.ZodType<T>, props: T, componentName: string): T {
  try {
    return schema.parse(props);
  } catch (error) {
    if (error instanceof z.ZodError) {
      console.error(`Invalid props passed to ${componentName}:`, error.errors);
    }
    return props; // Continue with original props
  }
}

/**
 * 객체 스키마에 추가 속성 허용 옵션 추가
 */
export function allowExtraProperties<T>(schema: z.ZodObject<any, any, any>) {
  return schema.passthrough() as unknown as z.ZodType<T>;
}

/**
 * 객체 스키마에서 추가 속성 차단 (엄격 모드)
 */
export function strictProperties<T>(schema: z.ZodObject<any, any, any>) {
  return schema.strict() as unknown as z.ZodType<T>;
}

/**
 * 스키마의 모든 필드를 선택적으로 변환 (부분 업데이트용)
 */
export function makePartial<T>(schema: z.ZodObject<any, any, any>) {
  return schema.partial() as unknown as z.ZodType<Partial<T>>;
}
