import { useMemo } from 'react';
import { FieldError } from 'react-hook-form';
import { MAX_INPUT_NUMBER } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { formatKoreanNumber } from '~/shared/lib/utils/format-korean-number';

type AmountDisplayProps = {
  trnscAmt: string;
  error: FieldError | undefined;
  handleClickInput: () => void;
  transactionLabel: string;
  allowZero?: boolean;
};

export const AmountDisplay = ({
  trnscAmt,
  error,
  handleClickInput,
  transactionLabel,
  allowZero = false,
}: AmountDisplayProps) => {
  const useFormattedAmount = (formatter: (num: number) => string) =>
    useMemo(() => {
      if (trnscAmt === '' || trnscAmt === null || trnscAmt === undefined) return null;
      const numAmt = Number(trnscAmt);
      if (Number.isNaN(numAmt)) return null;
      if (!allowZero && numAmt <= 0) return null;
      if (allowZero && numAmt < 0) return null;
      if (numAmt > MAX_INPUT_NUMBER) {
        return formatter(MAX_INPUT_NUMBER);
      }
      return formatter(numAmt);
    }, [allowZero, trnscAmt]);

  const displayAmount = useFormattedAmount((num) => num.toLocaleString());
  const displayKoreanAmount = useFormattedAmount((num) => (allowZero && num === 0 ? '0' : formatKoreanNumber(num)));

  return (
    <button type="button" className="amount-view" onClick={handleClickInput} data-testid="amount-display">
      {!displayAmount ? (
        <p className="amount-empty">{i18n.t('text:enterAmount', { transactionLabel })}</p>
      ) : (
        <div className="amount-preview on">
          <p className="amount-number">
            <span id="amount-preview">{displayAmount}</span> {i18n.t('won')}
          </p>
          {error ? (
            <p className="amount-info error">{error?.message}</p>
          ) : (
            <p className="amount-info">
              {displayKoreanAmount}
              {i18n.t('won')}
            </p>
          )}
        </div>
      )}
    </button>
  );
};
